minimal_patch:
在 syncDailyBoard 的循环内，将无条件 recoverArtifact(root,record,agent,seat) 改为：

const recovered = seat.assignment && seat.claim_verified && !seat.artifact && ['generation_started','generation_unknown_no_repurchase'].includes(seat.status)
  ? recoverArtifact(root,record,agent,seat)
  : false;

// recovery 成功后立即落入正常同步分支，不再先降级为 generation_unknown_no_repurchase
if (seat.assignment && seat.claim_verified && ['generation_failed_no_repurchase','failure_sync_unknown','failed_no_repurchase'].includes(seat.status)) {
  await syncFailedSeat({root,record,agent,seat,snapshot,command,readRemote,now});
  continue;
}
if (recovered) {
  // 已恢复为 generated_pending_sync，继续走下方 artifact 同步逻辑
} else if (seat.status === 'generation_started') {
  seat.status = 'generation_unknown_no_repurchase';
  seat.sync_reason = 'no_unique_complete_artifact_outcome_unknown';
  saveLedger(root,record);
  continue;
}
if (!seat.assignment || !seat.claim_verified || !seat.artifact || !['generated_pending_sync','sync_unknown','submitted_pending_review','review_unknown','completed_draft_review','rejected_draft_review'].includes(seat.status)) continue;

// 后续保持原有 validateArtifact / readRemote / snapshot / submit_task / review 逻辑不变
